try { eval("1") } catch e { print(e) }
try { exec("x = 1") } catch e { print(e) }
try { compile("1") } catch e { print(e) }
try { __import__("os") } catch e { print(e) }
try { load("1") } catch e { print(e) }

try { globals() } catch e { print(e) }
try { locals() } catch e { print(e) }
try { vars() } catch e { print(e) }
try { dir() } catch e { print(e) }
try { getattr({a: 1}, "a") } catch e { print(e) }
try { setattr({a: 1}, "a", 2) } catch e { print(e) }

try { open("x") } catch e { print(e) }
try { system("echo hi") } catch e { print(e) }
try { subprocess } catch e { print(e) }
try { os } catch e { print(e) }
try { sys } catch e { print(e) }

def inner() { return secret }
def outer() { let secret = 5
return inner() }
print(outer())

def meddle() { balance = 0
return balance }
def account() { let balance = 100
let seen = meddle()
return balance }
print(account())

def reset(acct) { acct.balance = 0 }
let mine = {balance: 100}
let yours = {balance: 100}
reset(mine)
print(mine.balance, yours.balance)

let big = 1
for i = 1 to 400 { big = big * 10 }
try { print(big * 1.0) } catch e { print("caught:", e) }

let big = 1
for i = 1 to 400 { big = big * 10 }
try { print(big / 3) } catch e { print("caught:", e) }

let big = 1
for i = 1 to 400 { big = big * 10 }
try { print(sqrt(big)) } catch e { print("caught:", e) }

let inf = num("1" + "0" * 400 + ".0")
try { print(floor(inf)) } catch e { print("caught:", e) }
try { print(round(inf - inf)) } catch e { print("caught:", e) }

let attempts = ["__builtins__", "__class__", "__import__", "builtins", "globals"]
print(len(attempts))
try { __builtins__ } catch e { print(e) }
try { __class__ } catch e { print(e) }
